drop policy if exists "Signed in users can comment on visible discussions" on public.community_comments; create policy "Signed in users can comment on visible discussions" on public.community_comments for insert to authenticated with check (author_id = auth.uid() and status = 'published' and exists (select 1 from public.community_discussions d where d.id = discussion_id and d.status = 'published') and (parent_comment_id is null or exists (select 1 from public.community_comments parent where parent.id = parent_comment_id and parent.discussion_id = discussion_id and parent.status = 'published')));